import http from 'node:http';
const port = Number(process.env.PORT || 3000);
let ready = true;
const server = http.createServer((req, res) => {
  if (req.url === '/ready') {
    res.writeHead(ready ? 200 : 503).end(ready ? 'ready' : 'draining');
  } else if (req.url === '/version') {
    res.end(process.env.RELEASE_ID || 'development');
  } else if (req.url === '/orders') {
    res.setHeader('content-type', 'application/json');
    res.end(JSON.stringify({orders: []}));
  } else {
    res.writeHead(404).end();
  }
});
server.listen(port, '0.0.0.0');
process.on('SIGTERM', () => {
  ready = false;
  server.close(() => process.exit(0));
  setTimeout(() => process.exit(1), 25000).unref();
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {total} from '../src/order.js';
test('sums line items', () => assert.equal(total([1200,800]), 2000));
test('rejects empty and invalid orders', () => {
  for (const items of [[], [0], [-1], [1.5]]) assert.throws(() => total(items));
});

import test from 'node:test';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
test('orders schema is usable', () => {
  const result = execFileSync('psql', [process.env.DATABASE_URL, '-v', 'ON_ERROR_STOP=1', '-Atc', "BEGIN; INSERT INTO orders(id,total_cents) VALUES ('ci-order',100); SELECT total_cents FROM orders WHERE id='ci-order'; ROLLBACK;"], {encoding:'utf8'});
  assert.match(result, /100/);
});

export function total(items) {
  if (!items.length || items.some(value => !Number.isInteger(value) || value <= 0)) throw new Error('Invalid order');
  return items.reduce((sum, value) => sum + value, 0);
}
